const now = new Date();
const y0 = now.getUTCFullYear();
const m0 = now.getUTCMonth();
const year  = m0 === 0 ? y0 - 1 : y0;
const month = m0 === 0 ? 12 : m0;
const start = new Date(Date.UTC(year, month - 1, 1));
const end   = new Date(Date.UTC(year, month, 0));
const fmt = (d) => d.toISOString().slice(0, 10);
const monthName = ['Januar','Februar','März','April','Mai','Juni','Juli','August','September','Oktober','November','Dezember'][month - 1];
return [{ json: {
  start_date: fmt(start),
  end_date:   fmt(end),
  month_label: `${monthName} ${year}`,
  month_iso:   `${year}-${String(month).padStart(2,'0')}`
}}];

const items = $input.all();
let totalSeconds = 0;
for (const item of items) {
  const groups = Array.isArray(item.json) ? item.json : [item.json];
  for (const group of groups) {
    const entries = group.time_entries || [];
    for (const e of entries) {
      totalSeconds += Number(e.seconds || 0);
    }
  }
}
const hours = Math.round((totalSeconds / 3600) * 100) / 100;
const rate  = Number($('Config').item.json.hourly_rate);
const vat   = Number($('Config').item.json.vat_percent);
const net   = Math.round(hours * rate * 100) / 100;
const vatAmount = Math.round(net * vat / 100 * 100) / 100;
const gross = Math.round((net + vatAmount) * 100) / 100;

const de = (n) => n.toLocaleString('de-DE', { minimumFractionDigits: 2, maximumFractionDigits: 2 });

if (hours <= 0) {
  throw new Error('No tracked hours in this period.');
}

return [{ json: {
  total_seconds: totalSeconds,
  hours, net, gross, vat_amount: vatAmount,
  hours_de: de(hours), rate_de: de(rate), net_de: de(net), vat_de: de(vatAmount), gross_de: de(gross),
  vat_percent: vat,
  month_label: $('Date Range (prev month)').item.json.month_label,
  month_iso:   $('Date Range (prev month)').item.json.month_iso
}}];
